187: export const WAND_NAME_PREFIX = {
188:   unicorn:'Dawn', phoenix:'Ember', dragon:'Wyrm', thunderbird:'Storm', thestral:'Veil',
189:   kelpie:'Tide', basilisk:'Venom', veela:'Enchant', troll:'Iron', augurey:'Mourn',
