191: }
192: export const WAND_NAME_SUFFIX = {
193:   oak:'Oath', willow:'Song', ash:'Ward', holly:'Pierce', hawthorn:'Knot', vine:'Coil',
194:   cedar:'Root', pear:'Hearth', walnut:'Gambit', redwood:'Crown', acacia:'Spur',
195:   rosewood:'Bloom', ebony:'Void', silverlime:'Moth', yew:'Grave', blackthorn:'Bane',
196:   elder:'Reverie', dragonbone:'Roar', moonash:'Veil', starglass:'Requiem',
