199: export function formatLength(len) {
200:   const whole = Math.floor(len)
201:   const frac = Math.round((len - whole) * 4)
202:   const glyphs = ['', '¼', '½', '¾']
203:   if (frac === 4) return `${whole + 1}″`
204:   return `${whole}${glyphs[frac]}″`
205: }
