207: export function computeWand({ woodId, coreId, length = 12, flex = 'supple', quality = 1 }) {
208:   const wood = woodById[woodId], core = coreById[coreId]
209:   if (!wood || !core) return null
210:   const flexDef = FLEXIBILITIES.find(f => f.id === flex) || FLEXIBILITIES[2]
211:   const q = clamp(quality, 0.85, 1.2)
212:   const stats = {
213:     power: Math.round(clamp(5 + (wood.stats.power + core.stats.power) * 3.55 + flexDef.mods.power * 1.7 + (length - 12) * 3.1 + (q - 1) * 95, 8, 99)),
214:     control: Math.round(clamp(5 + (wood.stats.control + core.stats.control) * 3.55 + flexDef.mods.control * 1.7 + (12 - length) * 1.4 + (q - 1) * 80, 8, 99)),
215:     finesse: Math.round(clamp(5 + (wood.stats.finesse + core.stats.finesse) * 3.55 + flexDef.mods.finesse * 1.7 + (12 - length) * 1.1 + (q - 1) * 85, 8, 99)),
216:   }
217:   const rating = Math.round((stats.power * 1.05 + stats.control + stats.finesse * 1.05) / 3)
218:   let rarityOrder = Math.max(RARITIES[wood.rarity].order, RARITIES[core.rarity].order)
219:   if (wood.rarity === core.rarity && rarityOrder >= 2) rarityOrder = Math.min(4, rarityOrder + 1)
220:   if (q >= 1.12 && rarityOrder < 4) rarityOrder = Math.min(4, rarityOrder + 1)
221:   const rarity = Object.keys(RARITIES).find(k => RARITIES[k].order === rarityOrder)
222: 
223:   const key = `${woodId}:${coreId}`
224:   const combo = COMBOS[key]
225:   let ability
226:   if (combo) {
227:     ability = { name: combo.name, desc: combo.desc, bonuses: combo.bonuses, special: combo.special, legendary: true }
228:   } else {
229:     const tags = new Set([...wood.tags, ...core.tags])
230:     const bonuses = {}
231:     for (const cat of Object.keys(CATEGORIES)) {
232:       if (wood.tags.includes(cat) && core.tags.includes(cat)) bonuses[cat] = 0.16
233:       else if (tags.has(cat)) bonuses[cat] = 0.07
234:     }
235:     const dominant = Object.entries(bonuses).sort((a, b) => b[1] - a[1])[0]?.[0] || 'offensive'
236:     ability = {
237:       name: `${WAND_NAME_PREFIX[coreId] || 'Wild'} Resonance`,
238:       desc: `An honest union of ${wood.name.toLowerCase()} and ${core.name.toLowerCase()}. ${CATEGORIES[dominant].label} magic is especially responsive.`,
239:       bonuses, special: null, legendary: false,
240:     }
241:   }
242: 
243:   const value = Math.round((wood.price + core.price * 1.25 + 22) * RARITIES[rarity].mult * (0.7 + rating / 110) * q)
244:   return {
245:     id: 'w' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
246:     wood: woodId, core: coreId, length, flex, quality: Number(q.toFixed(3)),
247:     name: `${WAND_NAME_PREFIX[coreId] || 'Wild'} ${WAND_NAME_SUFFIX[woodId] || 'Wand'}`,
248:     ability, stats, rating, rarity, value, rarityOrder,
249:     createdAt: Date.now(), equipped: false,
250:   }
251: }
