256:   const out = {}
257:   for (const cat of Object.keys(CATEGORIES)) {
258:     let a = 0.015
259:     if (wood?.tags.includes(cat)) a += 0.12
260:     if (core?.tags.includes(cat)) a += 0.1
261:     const bonus = wand.ability?.bonuses?.[cat]
262:     if (bonus) a += bonus
263:     out[cat] = clamp(a, 0, 0.75)
264:   }
265:   return out
266: }
