285: export function craftWand({ woodId, coreId, length, flex }) {
286:   const wood = woodById[woodId], core = coreById[coreId]
287:   if (!wood || !core) return { ok: false, error: 'Choose a wood and a core.' }
288:   if (countMat(woodId) < 1) return { ok: false, error: `You have no ${wood.name}.` }
289:   if (countMat(coreId) < 1) return { ok: false, error: `You have no ${core.name}.` }
290:   const cost = craftCost(woodId, coreId)
291:   if (state.player.gold < cost) return { ok: false, error: `You need ${cost} galleons to bind this wand.` }
292: 
293:   state.player.gold -= cost
294:   removeMat(woodId, 1)
295:   const kilnKeep = state.upgrades.kiln > 0 && Math.random() < 0.18 * state.upgrades.kiln
296:   if (!kilnKeep) removeMat(coreId, 1)
297:   const quality = clamp(0.93 + Math.random() * 0.11 + state.upgrades.bench * 0.018 + (state.flags.blessing ? 0.035 : 0.01), 0.9, 1.2)
298:   state.flags.blessing = false
299:   const wand = computeWand({ woodId, coreId, length, flex, quality })
300:   state.wands.push(wand)
301:   if (state.wands.length === 2) state.equipped = wand.id
302:   wand.equipped = wand.id === state.equipped
303:   state.metrics.wandsCrafted++
304:   addXp(18 + RARITIES[wand.rarity].order * 6)
305: 
306:   const key = `${woodId}:${coreId}`
307:   let discovery = null
308:   if (!state.discovered.includes(key)) {
309:     state.discovered.push(key)
