380: export function customerOffer(cust, wand) {
381:   const aff = wandAffinities(wand)[cust.pref] || 0
382:   let match = 0.72
383:   if (aff >= 0.24) match += 0.34
384:   else if (aff >= 0.14) match += 0.2
385:   else if (aff >= 0.07) match += 0.08
386:   if (cust.rarityPref === 'rare' && RARITIES[wand.rarity].order >= 2) match += 0.18
387:   if (wand.ability?.legendary) match += 0.1
388:   if (wand.control > 75) match += 0.04
389:   match += state.upgrades.ledger * 0.07
390:   const offer = Math.round(wand.value * match)
391:   const interested = offer <= cust.budget * 1.05
392:   return { offer: Math.min(offer, cust.budget), raw: offer, match, interested, affinity: aff }
393: }
