431:   const unlearned = spells.find(s => !state.learned[s.id])
432:   if (unlearned) return { spell: unlearned, isNew: true }
433:   if (!spells.length) return null
434:   const weakest = [...spells].sort((a, b) => masteryOf(a.id) - masteryOf(b.id))[0]
435:   return { spell: weakest, isNew: false }
