437: export function completeLesson(cat, perfect = false) {
438:   const target = nextLessonSpell(cat)
439:   if (!target) return null
440:   const { spell, isNew } = target
441:   const bonus = perfect ? 2 : 1
442:   if (isNew) {
443:     state.learned[spell.id] = { mastery: 0, learnedAt: Date.now() }
444:     state.metrics.spellsLearned++
445:   } else {
446:     state.learned[spell.id].mastery = Math.min(10, (state.learned[spell.id].mastery || 0) + bonus)
447:   }
448:   ensureLoadout()
449:   addXp(isNew ? 35 : 12)
450:   addRep(isNew ? 2 : 0)
