458: export function ensureLoadout() {
459:   const learned = learnedSpells().map(s => s.id)
460:   state.loadout = (state.loadout || []).filter(id => state.learned[id])
461:   for (const id of learned) {
462:     if (state.loadout.length >= 4) break
463:     if (!state.loadout.includes(id)) state.loadout.push(id)
464:   }
465:   if (state.loadout.length === 0 && learned.length) state.loadout = learned.slice(0, 4)
466: }
