481: export function spellPower(spell, wand = getEquippedWand()) {
482:   const aff = wandAffinities(wand)[spell.cat] || 0
483:   const rank = masteryRank(spell.id)
484:   const power = wand.stats.power / 100
485:   const level = 1 + (state.player.level - 1) * 0.05
486:   const passive = coreById[wand.core]?.id
487:   let coreMult = 1
488:   if (passive === 'dragon') coreMult += 0.1
489:   if (passive === 'voidheart') coreMult += 0.15
490:   if (passive === 'thunderbird' && spell.cat === 'elemental') coreMult += 0.15
491:   return (spell.power || 10) * (0.62 + power * 0.9) * (1 + aff) * (1 + (rank - 1) * 0.15) * level * coreMult
492: }
