        ui.toast('Restorative draught brewed', 'Health and mana restored. Professor Thorne pretends not to be impressed.', 'good', '☕')
        ui.objective('Potion brewed')
      }
      ui.updateHUD()
      break
    }
    case 'rest': {
      const res = restAtDorm()
      audio.play('magic')
