export function zoneAt(x, z) {
  let best = null, bestD = Infinity
  for (const zn of ZONES) {
    const d = Math.hypot(x - zn.pos[0], z - zn.pos[1])
    if (d < zn.radius && d < bestD) { best = zn; bestD = d }
  }
  return best || ZONES[0]
}

