:root{
  --ink:#090711;
  --panel:#151024;
  --panel-2:#1c1530;
  --gold:#d9b978;
  --gold-bright:#f5dfa6;
  --gold-dim:#9c7c43;
  --violet:#9a7be0;
  --violet-dim:#5c478f;
  --teal:#6fd8c4;
  --rose:#e58b9a;
